<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {request} from '@/api/client'
import {onBeforeRouteLeave} from 'vue-router'
import {authStore} from '@/stores/auth'
import DialogPanel from '@/components/DialogPanel.vue'
import {uiText,uiLanguage} from '@/i18n'
import SelectField from '@/components/SelectField.vue'
import HelpHint from '@/components/HelpHint.vue'
import Prism from 'prismjs'
import 'prismjs/components/prism-python'
import 'prismjs/components/prism-c'
import 'prismjs/components/prism-java'
import {samples,languageNames,occurrences,valueText,arrayScale,traceSvg,type Language,type Run,type RunSummary,type Value} from '@/lib/codeLab'

const language=ref<Language>('auto'),source=ref(samples.python.source),entry=ref('sort'),args=ref(samples.python.args)
const example=ref<Exclude<Language,'auto'>>('python'),busy=ref(false),error=ref(''),historyError=ref('')
const run=ref<Run>(),history=ref<RunSummary[]>([]),stepIndex=ref(0),selectedLine=ref(0),speed=ref(700),playing=ref(false)
const frameIndex=ref(-1),view=ref<'replay'|'overview'>('replay'),confirmDelete=ref(''),pending=ref('')
const editorKey=()=>JSON.stringify([source.value,entry.value,args.value,language.value])
const savedEditor=ref(editorKey()),dirty=computed(()=>editorKey()!==savedEditor.value),discardOpen=ref(false)
let discardAction:(()=>void)|undefined,discardCancel:(()=>void)|undefined
function confirmDiscard(action:()=>void,cancel?:()=>void){if(!dirty.value){action();return}discardAction=action;discardCancel=cancel;discardOpen.value=true}
function decideDiscard(accept:boolean){const action=accept?discardAction:discardCancel;discardOpen.value=false;discardAction=undefined;discardCancel=undefined;action?.()}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value&&authStore.state.user){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(()=>{if(!dirty.value||!authStore.state.user)return true;return new Promise<boolean>(resolve=>confirmDiscard(()=>resolve(true),()=>resolve(false)))})
let disposed=false,version=0,timer=0;const controller=new AbortController()
const trace=computed(()=>run.value?.result),step=computed(()=>trace.value?.steps[stepIndex.value])
const frame=computed(()=>{const frames=step.value?.frames||[];return frames[frameIndex.value<0?frames.length-1:Math.min(frameIndex.value,frames.length-1)]})
const previousFrame=computed(()=>{const index=frameIndex.value<0?(step.value?.frames.length||1)-1:frameIndex.value;const previous=trace.value?.steps[stepIndex.value-1]?.frames[index];return previous?.name===frame.value?.name?previous:undefined})
const arrays=computed(()=>Object.entries(frame.value?.variables||{}).filter(([,v])=>Array.isArray(v)) as [string,Value[]][])
const scalars=computed(()=>Object.entries(frame.value?.variables||{}).filter(([,v])=>!Array.isArray(v)))
const lines=computed(()=>{
  const text=run.value?.source||source.value,lang=trace.value?.language||'python'
  const grammar=Prism.languages[lang]||Prism.languages.plain
  return text.split('\n').map(line=>grammar?Prism.highlight(line,grammar,lang):line.replace(/&/g,'&amp;').replace(/</g,'&lt;'))
})
const lineSteps=computed(()=>trace.value&&selectedLine.value?occurrences(trace.value,selectedLine.value):[])
const loopTotal=computed(()=>Object.values(trace.value?.loopCounts||{}).reduce((a,b)=>a+b,0))
const callTotal=computed(()=>Object.values(trace.value?.callCounts||{}).reduce((a,b)=>a+b,0))
const events:Record<string,string>={statement:'语句完成',branch:'分支判断',loop:'进入循环','loop-end':'循环结束',condition:'循环条件',update:'循环更新',call:'进入函数',return:'函数返回','return-value':'返回值',break:'跳出循环',continue:'下一轮循环'}
const changed=(name:string,value:Value)=>valueText(previousFrame.value?.variables[name])!==valueText(value)
const cellChanged=(name:string,i:number,value:Value)=>{const before=previousFrame.value?.variables[name];return !Array.isArray(before)||valueText(before[i])!==valueText(value)}
function stop(){playing.value=false;window.clearTimeout(timer)}
function select(index:number){stop();stepIndex.value=Math.max(0,Math.min(index,(trace.value?.steps.length||1)-1));frameIndex.value=-1}
function advance(){if(disposed||!playing.value)return;if(stepIndex.value>=(trace.value?.steps.length||0)-1){stop();return}stepIndex.value++;frameIndex.value=-1;timer=window.setTimeout(advance,speed.value)}
function play(){if(playing.value){stop();return}if(!trace.value?.steps.length)return;if(stepIndex.value>=trace.value.steps.length-1)stepIndex.value=0;playing.value=true;timer=window.setTimeout(advance,speed.value)}
function setLine(line:number){selectedLine.value=line;const steps=trace.value?occurrences(trace.value,line):[];if(steps.length)select(steps[0])}
function loadExample(){if(busy.value||pending.value)return;confirmDiscard(applyExample)}
function applyExample(){const s=samples[example.value];source.value=s.source;entry.value=s.entry;args.value=s.args;language.value=example.value;error.value='';savedEditor.value=editorKey()}
async function loadHistory(){try{const items=await request<RunSummary[]>('/code-lab/runs',{signal:controller.signal});if(!disposed){history.value=items;historyError.value=''}}catch(e){if(!disposed)historyError.value=(e as Error).message}}
function show(value:Run){stop();run.value=value;stepIndex.value=0;frameIndex.value=-1;selectedLine.value=0;view.value='replay'}
async function execute(){
  if(busy.value||pending.value)return;error.value='';stop();let argumentsValue:unknown
  try{argumentsValue=JSON.parse(args.value);if(!Array.isArray(argumentsValue))throw new Error()}catch{error.value='参数格式不正确，请填写 JSON 数组。';return}
  if(new TextEncoder().encode(source.value).length>16000||source.value.split('\n').length>400){error.value='代码最多 400 行、16 KB。';return}
  busy.value=true;const v=++version
  try{const value=await request<Run>('/code-lab/runs',{method:'POST',signal:controller.signal,body:JSON.stringify({source:source.value,language:language.value,entry:entry.value.trim(),arguments:argumentsValue})});if(!disposed&&version===v){show(value);savedEditor.value=editorKey();await loadHistory()}}
  catch(e){if(!disposed&&version===v)error.value=(e as Error).message}
  finally{if(!disposed&&version===v)busy.value=false}
}
function openHistory(id:string){if(busy.value||pending.value)return;confirmDiscard(()=>{void loadRun(id)})}
async function loadRun(id:string){pending.value=id;error.value='';try{const value=await request<Run>('/code-lab/runs/'+id,{signal:controller.signal});if(!disposed){show(value);source.value=value.source;entry.value=value.entry;args.value=JSON.stringify(value.arguments);language.value=value.result.language||'auto';savedEditor.value=editorKey()}}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)pending.value=''}}
async function removeHistory(id:string){if(pending.value||busy.value)return;pending.value=id;try{await request('/code-lab/runs/'+id,{method:'DELETE',signal:controller.signal});if(!disposed){confirmDelete.value='';await loadHistory();if(run.value?.id===id){stop();run.value=undefined}}}catch(e){if(!disposed)historyError.value=(e as Error).message}finally{if(!disposed)pending.value=''}}
function download(kind:'json'|'svg'){
  if(!run.value)return
  const content=kind==='json'?JSON.stringify(run.value,null,2):traceSvg(run.value.result,stepIndex.value)
  const url=URL.createObjectURL(new Blob([content],{type:kind==='json'?'application/json':'image/svg+xml'}))
  const a=document.createElement('a');a.href=url;a.download=`code-trace-${run.value.id}.${kind}`;a.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000)
}
function visibility(){if(document.hidden)stop()}
watch(speed,()=>{if(playing.value){window.clearTimeout(timer);timer=window.setTimeout(advance,speed.value)}})
onMounted(()=>{void loadHistory();document.addEventListener('visibilitychange',visibility);window.addEventListener('beforeunload',beforeUnload)})
onBeforeUnmount(()=>{disposed=true;version++;controller.abort();stop();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('beforeunload',beforeUnload);decideDiscard(false)})
</script>

<template>
  <div class="page-shell code-lab">
    <header class="page-heading lab-heading"><div><p class="page-kicker">CODE / OBSERVE / UNDERSTAND</p><h1>{{uiText('让代码的每一步，看得见')}}</h1><p>{{uiText('写下代码，观察变量如何变化。回到任意一步，理解程序为什么这样运行。')}}</p></div><span class="lab-badge">C · Python · Java · JavaScript</span></header>
    <p v-if="error" class="inline-alert inline-alert--error" role="alert">{{uiText(error)}}</p>
    <div class="lab-workspace">
      <section class="lab-editor lab-panel" :aria-busy="busy">
        <div class="lab-section-heading"><h2>{{uiText('代码')}}</h2><span>{{source.split('\n').length}} / 400 {{uiText('行')}}</span></div>
        <div class="lab-controls"><label>{{uiText('语言')}}<SelectField><select v-model="language" class="field-input" :disabled="busy||!!pending"><option v-for="(name,key) in languageNames" :key="key" :value="key">{{uiText(name)}}</option></select></SelectField></label><label>{{uiText('示例')}}<SelectField><select v-model="example" class="field-input" :disabled="busy||!!pending"><option value="python">Python · {{uiText('冒泡排序')}}</option><option value="c">C · {{uiText('冒泡排序')}}</option><option value="java">Java · {{uiText('冒泡排序')}}</option><option value="javascript">JavaScript · {{uiText('冒泡排序')}}</option></select></SelectField></label><button type="button" class="button button--ghost" :disabled="busy||!!pending" @click="loadExample">{{uiText('载入')}}</button></div>
        <label class="sr-only" for="code-source">{{uiText('代码内容')}}</label><textarea id="code-source" v-model="source" class="lab-source" spellcheck="false" autocapitalize="off" autocomplete="off" :disabled="busy||!!pending" maxlength="16000" />
        <div class="lab-inputs"><label>{{uiText('入口函数')}} <HelpHint label="入口函数" text="C / Java 自动寻找 main。没有 main 时，填写要调用的函数名。Python / JavaScript 留空会从顶层执行；填写函数名只运行该函数。"/><input v-model="entry" class="field-input" :disabled="busy||!!pending" placeholder="sort" maxlength="60" autocomplete="off" /></label><label>{{uiText('参数（JSON）')}} <HelpHint label="参数说明" text="最外层数组的每一项对应一个函数参数。例如 [[5,2,8,1],4] 表示传入一个数组和整数 4。"/><input v-model="args" class="field-input lab-mono" :disabled="busy||!!pending" maxlength="8000" placeholder="[[5, 2, 8, 1]]" spellcheck="false" /></label></div>
        <div class="lab-run-row"><span>{{uiText('独立受限解释环境 · 无外部 AI 调用')}}</span><button class="button button--dark" :disabled="busy||!!pending||!source.trim()" @click="execute">{{uiText(busy?'正在执行…':'运行并可视化')}} <span aria-hidden="true">↗</span></button></div>
      </section>
      <section class="lab-panel lab-viewer" :aria-label="uiText('执行回放')">
        <div class="lab-section-heading"><h2>{{uiText('执行回放')}}</h2><div v-if="trace" class="lab-tabs"><button :aria-pressed="view==='replay'" @click="view='replay'">{{uiText('逐步')}}</button><button :aria-pressed="view==='overview'" @click="view='overview'">{{uiText('概览')}}</button></div></div>
        <div v-if="!trace" class="lab-empty"><div class="lab-orbit" aria-hidden="true"><i/><i/><i/><span>{ }</span></div><h3>{{uiText('从一次变化，理解整个过程')}}</h3><p>{{uiText('运行左侧示例，查看数组交换、循环与函数调用。你的执行记录仅自己可见。')}}</p><div class="lab-empty-flow"><span>{{uiText('输入')}}</span><b>→</b><span>{{uiText('执行')}}</span><b>→</b><span>{{uiText('观察')}}</span></div></div>
        <template v-else>
          <div class="lab-status" role="status"><span :class="['status-dot',trace.status]"/>{{uiText(trace.status==='completed'?'执行完成':trace.status==='limited'?'达到限制':'执行中断')}}<span>{{trace.language||language}} · {{trace.steps.length}} {{uiText('步')}}</span></div>
          <p v-if="trace.error" class="inline-alert inline-alert--error" role="alert">{{uiText('第')}} {{trace.error.line}} {{uiText('行')}} · {{uiText(trace.error.message)}}</p>
          <template v-if="view==='replay'&&step">
            <div class="lab-playback"><button class="button button--ghost" :disabled="stepIndex===0" :aria-label="uiText('上一步')" @click="select(stepIndex-1)">←</button><button class="button button--dark" @click="play">{{uiText(playing?'暂停':'播放')}}</button><button class="button button--ghost" :disabled="stepIndex===trace.steps.length-1" :aria-label="uiText('下一步')" @click="select(stepIndex+1)">→</button><span class="lab-mono">{{stepIndex+1}} / {{trace.steps.length}}</span><SelectField><select v-model.number="speed" class="compact-select" :aria-label="uiText('播放速度')"><option :value="1400">0.5×</option><option :value="700">1×</option><option :value="350">2×</option></select></SelectField></div>
            <input class="lab-timeline" type="range" :value="stepIndex" min="0" :max="trace.steps.length-1" :aria-label="uiText('选择执行步骤')" @input="select(Number(($event.target as HTMLInputElement).value))"/>
            <div class="lab-step-heading"><strong>{{uiText('第')}} {{step.line}} {{uiText('行')}}</strong><span>{{uiText(events[step.event]||step.event)}}<template v-if="step.detail!==undefined"> · {{valueText(step.detail)}}</template></span></div>
            <nav class="lab-stack" :aria-label="uiText('调用栈')"><button v-for="(f,i) in step.frames" :key="i" :class="{selected:frame===f}" @click="frameIndex=i">{{f.name}}<small>#{{i}}</small></button></nav>
            <div class="lab-values"><div v-for="([name,value]) in scalars" :key="name" :class="['lab-scalar',{changed:changed(name,value)}]"><code>{{name}}</code><strong>{{valueText(value)}}</strong></div><p v-if="!arrays.length&&!scalars.length" class="field-hint">{{uiText('此步骤尚无变量。')}}</p></div>
            <div v-for="([name,values]) in arrays" :key="name" class="lab-array"><div><code>{{name}}</code><span>{{values.length}} {{uiText('项')}}</span></div><div class="lab-array-cells"><div v-for="(value,i) in values" :key="i" :class="['lab-cell',{changed:cellChanged(name,i,value)}]"><div class="lab-bar-track"><i :style="{height:(typeof value==='number'?Math.max(6,Math.abs(value)/arrayScale(values)*85):10)+'%'}"/></div><strong>{{valueText(value)}}</strong><small>{{i}}</small></div><span v-if="!values.length">[ ]</span></div></div>
          </template>
          <div v-else-if="view==='overview'" class="lab-overview"><div class="lab-metrics"><div><span>{{uiText('记录步骤')}}</span><strong>{{trace.steps.length}}</strong></div><div><span>{{uiText('循环迭代')}}</span><strong>{{loopTotal}}</strong></div><div><span>{{uiText('函数调用')}}</span><strong>{{callTotal}}</strong></div><div><span>{{uiText('表达式与语句求值')}}</span><strong>{{trace.operations||0}}</strong></div></div><h3>{{uiText('执行分布')}}</h3><div class="lab-heat"><button v-for="(count,line) in trace.lineCounts" :key="line" :title="`${uiText('第')} ${line} ${uiText('行')} · ${count}`" @click="view='replay';setLine(Number(line))"><span>L{{line}}</span><i :style="{width:(count/Math.max(1,...Object.values(trace.lineCounts||{}))*100)+'%'}"/><b>{{count}}</b></button></div><h3>{{uiText('复杂度估算')}}</h3><p class="lab-complexity">{{trace.complexity?.estimate==='unknown'?uiText('暂无法可靠推断'):trace.complexity?.estimate||'—'}}</p><p class="field-hint">{{uiText(trace.complexity?.basis||'')}}</p><p class="field-hint">{{uiText('单次运行的步数不能证明渐进复杂度。未完成的执行只展示已记录的部分。')}}</p></div>
          <div class="lab-output"><h3>{{uiText('输出与返回值')}}</h3><pre>{{view==='replay'&&step?(trace.output||'').slice(0,step.outputLength):trace.output||''}}{{trace.status==='completed'&&(view==='overview'||stepIndex===trace.steps.length-1)?'\n↳ '+valueText(trace.result):''}}</pre></div>
        </template>
      </section>
    </div>
    <section v-if="trace?.steps.length" class="lab-panel lab-recorded-code"><div class="lab-section-heading"><div><h2>{{uiText('源码与执行位置')}}</h2><p class="field-hint">{{uiText('点击行号可查看该行每次执行。这里始终显示本次回放对应的源码。')}}</p></div><div class="lab-export"><button class="button button--ghost" @click="download('json')">{{uiText('导出回放')}}</button><button class="button button--ghost" @click="download('svg')">{{uiText('导出当前图像')}}</button></div></div><div v-if="lineSteps.length" class="lab-occurrences"><span>L{{selectedLine}} · {{lineSteps.length}} {{uiText('次执行')}}</span><SelectField><select :value="stepIndex" class="compact-select" :aria-label="uiText('选择此行的执行次数')" @change="select(Number(($event.target as HTMLSelectElement).value))"><option v-if="!lineSteps.includes(stepIndex)" :value="stepIndex" disabled>{{uiText('选择执行次数')}}</option><option v-for="(index,i) in lineSteps" :key="index" :value="index">#{{i+1}} · {{uiText('第')}} {{index+1}} {{uiText('步')}}</option></select></SelectField></div><div class="lab-source-replay"><div v-for="(line,i) in lines" :key="i" :class="['lab-code-line',{current:step?.line===i+1}]"><button :disabled="!trace.lineCounts?.[i+1]" :aria-label="`${uiText('第')} ${i+1} ${uiText('行')}`" @click="setLine(i+1)">{{i+1}}<small>{{trace.lineCounts?.[i+1]||'·'}}</small></button><code v-html="line||' '"/></div></div></section>
    <div class="lab-bottom"><section class="lab-panel"><div class="lab-section-heading"><h2>{{uiText('我的执行记录')}}</h2><button class="table-action" :disabled="busy||!!pending" @click="loadHistory">{{uiText('刷新')}}</button></div><p class="field-hint">{{uiText('自动保留最近 20 次运行。旧记录自动清理，需要长期保留时可导出回放。')}}</p><p v-if="historyError" class="inline-alert inline-alert--error" role="alert">{{uiText(historyError)}}</p><p v-if="!history.length" class="field-hint">{{uiText('还没有执行记录。')}}</p><div class="lab-history"><article v-for="item in history" :key="item.id"><button class="lab-history-open" :disabled="busy||!!pending" @click="openHistory(item.id)"><strong>{{item.language}} <span>{{item.entry||uiText('顶层执行')}}</span></strong><small>{{new Date(item.createdAt).toLocaleString(uiLanguage==='en'?'en-US':'zh-CN')}} · {{uiText(item.status==='completed'?'完成':item.status==='limited'?'达到限制':'中断')}}</small></button><template v-if="confirmDelete===item.id"><button class="table-action" :disabled="busy||!!pending" @click="removeHistory(item.id)">{{uiText('确认删除')}}</button><button class="table-action" :disabled="!!pending" @click="confirmDelete=''">{{uiText('取消')}}</button></template><button v-else class="table-action" :disabled="busy||!!pending" @click="confirmDelete=item.id">{{uiText('删除')}}</button></article></div></section><section class="lab-panel lab-guide"><p class="page-kicker">A SMALL, OBSERVABLE WORLD</p><h2>{{uiText('先从一小段算法开始')}}</h2><ol><li>{{uiText('选择示例，或粘贴自己的算法代码。语言不明确时手动选择。')}}</li><li>{{uiText('没有 main 也可以运行：填写函数名，再按参数顺序填写 JSON 数组。')}}</li><li>{{uiText('点击运行，再播放或拖动时间轴。点击源码行号可查看第几次执行。')}}</li></ol><details><summary>{{uiText('支持范围与执行限制')}}</summary><p>{{uiText('支持变量、条件、循环、函数、递归和一维数组的常见算法子集。C / Java 以 32 位整数算法为主，溢出会停止；不支持指针、类实例、导入库、文件与网络操作。')}}</p><p>{{uiText('这是受限教学解释器，不是完整语言编译器。数组最多 128 项、调用栈 24 层、回放 1000 步、内部求值 20000 次。超限会停止并标注，已有步骤可继续查看。')}}</p><p>{{uiText('开启函数入口时仅执行该函数；函数所需数据通过参数传入。当前不支持依赖顶层初始化或全局变量的入口。')}}</p></details></section></div>
    <DialogPanel v-if="discardOpen" :title="uiText('替换尚未运行的代码？')" @close="decideDiscard(false)"><p>{{uiText('当前编辑尚未保存在执行记录中。继续会离开或替换这些内容。')}}</p><div class="lab-export"><button class="button button--ghost" @click="decideDiscard(false)">{{uiText('继续编辑')}}</button><button class="button button--dark" @click="decideDiscard(true)">{{uiText('放弃更改并继续')}}</button></div></DialogPanel>
  </div>
</template>

<style scoped>
.code-lab{--lab-accent:var(--green)}.lab-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:24px}.lab-heading h1{font-size:clamp(28px,3vw,42px)}.lab-badge{font-size:12px;letter-spacing:.06em;white-space:nowrap;color:var(--muted);padding-bottom:10px}.lab-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.08fr);gap:24px;align-items:start}.lab-panel{min-width:0;padding:26px;border:1px solid var(--line);border-radius:16px;background:var(--paper);box-shadow:0 8px 35px -30px var(--lab-accent)}.lab-section-heading{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:20px}.lab-section-heading h2{font-size:18px;margin:0}.lab-section-heading>span{font-size:12px;color:var(--muted)}.lab-controls{display:flex;align-items:end;gap:10px}.lab-controls label{flex:1;min-width:0}.lab-controls label,.lab-inputs label{font-size:12px;display:block;color:var(--muted)}.lab-controls :deep(.field-input){margin-top:8px}.lab-source{display:block;width:100%;box-sizing:border-box;min-height:330px;resize:vertical;border:1px solid var(--line);border-radius:10px;padding:20px;margin:18px 0;background:color-mix(in srgb,var(--lab-accent) 3%,var(--paper));color:var(--ink);font:13px/1.85 Consolas,'Cascadia Code',monospace;tab-size:4;white-space:pre;overflow:auto}.lab-inputs{display:grid;grid-template-columns:1fr 1.6fr;gap:14px}.lab-inputs input{margin-top:8px}.lab-run-row{display:flex;align-items:center;gap:16px;justify-content:space-between;margin-top:22px}.lab-run-row>span{font-size:11px;color:var(--muted)}.lab-run-row button{white-space:nowrap;gap:20px}.lab-viewer{min-height:588px}.lab-empty{min-height:470px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center}.lab-empty h3{font-size:20px;font-weight:500;margin:22px 0 8px}.lab-empty p{max-width:330px;font-size:13px;color:var(--muted);line-height:1.9}.lab-orbit{position:relative;width:140px;height:140px;display:grid;place-items:center;c